import DefaultTheme from "vitepress/theme";
import type { Theme } from "vitepress";
import { theme, useOpenapi } from "vitepress-openapi/client";
import "vitepress-openapi/dist/style.css";
// Generated by scripts/build-openapi.mjs before vitepress dev/build (INT-302).
import spec from "../../public/openapi/public.v1.json" with { type: "json" };

export default {
  extends: DefaultTheme,
  async enhanceApp({ app }) {
    useOpenapi({
      spec,
      config: {
        // INT-303 — let operators paste their own gateway URL in the playground.
        server: {
          allowCustomServer: true,
        },
      },
    });
    theme.enhanceApp({ app });
  },
} satisfies Theme;
